sys_variable_value.value:
(function execute(inputs, outputs) {
    var utils = new LabTestUtils();

    switch (inputs.mode) {
        case 'result':
            outputs.output = utils.getLabTestResults(inputs.test_id) || 'Result not found';
            break;

        case 'ready':
            outputs.output = utils.checkLabTestResultsReady(inputs.test_id);
            break;

        case 'by_patient':
            outputs.output = JSON.stringify(utils.getLabTestsByPatientId(inputs.patient_id));
            break;

        case 'by_date':
            outputs.output = JSON.stringify(utils.getLabTestsByDate(inputs.date_str));
            break;

        default:
            outputs.output = 'Invalid mode provided';
    }
})(inputs, outputs);

